import { calculateDilution } from './src/domain/calculations.mjs';
import { addBatch, addEvaluation, addExperiment, addJournalEntry, addMaterial, addMaterialLot, addRevision, addStockMovement, batchSummary, compareBatchToPlan, importLegacyCompanionEntries, inventorySummary, lotMovementHistory, reconcileLot, reconcileLotOpening, stockBalance, stockStatus, updateJournalEntry } from './src/domain/store.mjs';
import { createLocalStorageAdapter, bootstrapState, persistState, applyBackupImport, previewBackupImport } from './src/domain/persistence.mjs';
import { parseBackup, serializeBackup } from './src/domain/backup.mjs';
import { compareRevisions } from './src/domain/comparison.mjs';
import { initScentCompanion } from './src/ui/companion.mjs';

const $ = selector => document.querySelector(selector);
const persistence = createLocalStorageAdapter();
const boot = bootstrapState(persistence);
let state = boot.state;
let storageLocked = boot.locked;
const loadError = boot.error;
if (!storageLocked) {
  const legacyCompanion = importLegacyCompanionEntries(state, persistence.storage);
  if (legacyCompanion.imported) {
    try { state = legacyCompanion.state; persistence.save(state); }
    catch { state = legacyCompanion.state; }
  }
}
let currentScreen = 'journal';
let companionApi;
let pendingBackup = null;
const today = () => new Date().toISOString().slice(0, 10);
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[char]));
const formatDate = value => value ? new Intl.DateTimeFormat('en', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value)) : 'Date not recorded';
const toast = message => { const node = $('#toast'); node.textContent = message; node.classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => node.classList.remove('show'), 2200); };
const persist = (next, { allowLocked = false } = {}) => {
  const result = persistState(persistence, next, { locked: storageLocked, allowLocked });
  if (!result.ok) { toast(result.error); return false; }
  state = result.state;
  storageLocked = false;
  renderAll();
  companionApi?.render();
  return true;
};
function openDialog(id) { $( `#${id}`).showModal(); }
function closeDialog(id) { $( `#${id}`).close(); }
function tags(value) { return String(value || '').split(',').map(item => item.trim()).filter(Boolean); }
function statusClass(status) { return String(status || '').toLowerCase(); }
function getExperiment(id) { return state.experiments.find(item => item.id === id); }

function renderJournal() {
  const query = ($('#journal-search')?.value || '').toLowerCase(); const filter = $('#journal-filter')?.value || '';
  const entries = state.journalEntries.filter(entry => { const haystack = [entry.title, entry.purpose, entry.opening, entry.heart, entry.dryDown, ...(entry.tags || []), ...(entry.descriptors || [])].join(' ').toLowerCase(); return haystack.includes(query) && (!filter || filter === (entry.measuredResults ? 'measured' : 'personal')); });
  $('#journal-result-count').textContent = `${entries.length} record${entries.length === 1 ? '' : 's'}`;
  $('#journal-list').innerHTML = entries.length ? entries.map(entry => `<article class="record" data-journal-id="${esc(entry.id)}"><div class="record-top"><div><h3>${esc(entry.title)}</h3><span class="record-date">${formatDate(entry.observedAt)} · ${esc(entry.medium || 'Medium not recorded')}</span></div><div class="record-actions"><button class="icon-button" data-action="duplicate-journal">Duplicate</button><button class="icon-button" data-action="open-journal">Open</button></div></div><p class="record-summary">${esc(entry.overall || entry.opening || entry.personalNotes || 'No sensory summary recorded yet.')}</p><div class="chips">${(entry.descriptors || []).map(item => `<span class="chip">${esc(item)}</span>`).join('')}</div></article>`).join('') : '<div class="empty-state"><strong>No entries match this view.</strong>Record an observation or adjust the search.</div>';
}

function renderExperiments() {
  const query = ($('#experiment-search')?.value || '').toLowerCase(); const status = $('#experiment-status')?.value || '';
  const experiments = state.experiments.filter(item => `${item.title} ${item.experimentId} ${item.objective}`.toLowerCase().includes(query) && (!status || item.status === status));
  $('#experiment-list').innerHTML = experiments.length ? experiments.map(experiment => { const revisions = state.revisions.filter(item => experiment.formulaRevisionIds.includes(item.id)); const batches = state.batches.filter(item => experiment.batchIds.includes(item.id)); return `<article class="experiment-card" data-experiment-id="${esc(experiment.id)}"><div class="experiment-meta"><span>${esc(experiment.experimentId)}</span><span class="status ${statusClass(experiment.status)}">${esc(experiment.status)}</span></div><h3>${esc(experiment.title)}</h3><p>${esc(experiment.objective || 'No objective recorded.')}</p><div class="chips"><span class="chip">${revisions.length} revision${revisions.length === 1 ? '' : 's'}</span><span class="chip">${batches.length} batch${batches.length === 1 ? '' : 'es'}</span><span class="chip">${experiment.evaluationIds?.length || 0} evaluations</span></div></article>`; }).join('') : '<div class="empty-state"><strong>No experiments yet.</strong>Create a trial to preserve its formula history.</div>';
}

function renderMaterials() {
  const summary = inventorySummary(state);
  $('#inventory-summary').innerHTML = [['LOTS', summary.lots.length], ['KNOWN ON-HAND', summary.lots.filter(item => item.balanceKnown).length], ['RECONCILIATION NEEDED', summary.unknownLots.length], ['LOW STOCK / DATE WARNINGS', summary.lowStock.length + summary.dateWarnings.length]].map(([label, value]) => `<div><span>${label}</span><strong>${value}</strong></div>`).join('');
  const warnings = [...summary.unknownLots.map(item => `<div class="inventory-warning"><strong>${esc(item.materialName)} · ${esc(item.lot.lotCode || item.lot.id)}</strong><span>Opening quantity unknown. ${item.balance == null ? 'No compatible quantity is recorded yet.' : `Recorded balance ${item.balance.toFixed(4)} ${esc(item.unit)} is a consumption floor, not measured on-hand stock.`}</span></div>`), ...summary.lowStock.map(item => `<div class="inventory-warning"><strong>Low stock · ${esc(item.materialName)} · ${esc(item.lot.lotCode || item.lot.id)}</strong><span>${item.balance.toFixed(4)} ${esc(item.unit)} at or below threshold ${esc(item.lot.lowStockThreshold)} ${esc(item.unit)}.</span></div>`), ...summary.dateWarnings.map(item => `<div class="inventory-warning"><strong>Date reminder · ${esc(item.materialName)} · ${esc(item.lot.lotCode || item.lot.id)}</strong><span>${esc(item.warnings.filter(warning => warning.includes('date')).join(' '))} Operational reminder only; not a safety determination.</span></div>`)].join('');
  $('#inventory-warnings').innerHTML = warnings || '<div class="inventory-ok">No inventory warnings for recorded dates, thresholds, or opening balances.</div>';
  $('#material-list').innerHTML = state.materials.length ? `<table><thead><tr><th>MATERIAL</th><th>LOT / ON-HAND</th><th>IDENTITY &amp; STORAGE</th><th>HISTORY</th><th>ACTIONS</th></tr></thead><tbody>${state.materials.map(material => { const lots = material.lots || []; const used = state.batches.flatMap(batch => batch.actualAdditions || []).filter(addition => addition.materialId === material.id).length; return `<tr><td><strong>${esc(material.name)}</strong><br><span class="muted">${esc(material.supplier || 'Supplier not recorded')} · ${used} batch use${used === 1 ? '' : 's'}</span></td><td>${lots.length ? lots.map(lot => { const status = stockStatus(state, lot.id); const unit = status.unit || '?'; const history = lotMovementHistory(state, lot.id); const label = lot.lotCode || lot.id; const balance = status.balanceKnown ? `${status.balance.toFixed(4)} ${esc(unit)}` : `Unknown${status.balance == null ? '' : ` · floor ${status.balance.toFixed(4)} ${esc(unit)}`}`; return `<div class="lot-ledger"><div class="lot-meta"><strong>${esc(label)}</strong><small>${esc(lot.receivedAt || 'Received date not recorded')} · ${lot.purity == null ? 'Purity unknown' : `${lot.purity}% purity`} · ${lot.expiryDate ? `Expiry ${esc(lot.expiryDate)}` : 'Expiry unknown'}</small><span class="${status.balanceKnown ? '' : 'unknown-stock'}">On-hand: ${balance}</span></div><div class="inventory-actions"><button class="icon-button" data-action="new-movement" data-material-id="${esc(material.id)}" data-lot-id="${esc(lot.id)}" type="button">Movement</button><button class="icon-button" data-action="reconcile-lot" data-lot-id="${esc(lot.id)}" type="button">Reconcile</button></div><details><summary>${history.length} movement${history.length === 1 ? '' : 's'} · ${history.filter(item => item.batchId).length} linked batch${history.filter(item => item.batchId).length === 1 ? '' : 'es'}</summary><ol class="ledger-history">${history.map(movement => { const sign = ['opening', 'receipt', 'return'].includes(movement.movementType) || (['adjustment', 'correction'].includes(movement.movementType) && movement.direction === 'increase') ? '+' : '-'; const batch = movement.batchId ? state.batches.find(item => item.id === movement.batchId) : null; return `<li><span class="${sign === '+' ? 'movement-positive' : 'movement-negative'}">${sign}${esc(movement.quantity)} ${esc(movement.unit)}</span> · ${esc(movement.movementType)} · ${formatDate(movement.occurredAt)}${batch ? ` · ${esc(batch.batchCode)}` : ''}${movement.note ? ` · ${esc(movement.note)}` : ''}</li>`; }).join('')}</ol></details></div>`; }).join('') : '<span class="muted">No lots recorded.</span>'}</td><td><div>${esc(material.canonicalIdentity || 'Identity not recorded')}</div><small class="muted">${esc(material.productReference || 'Product reference not recorded')}<br>${esc(material.storageNotes || 'Storage notes not recorded')}<br>${esc(material.safetyReference || 'Safety reference not recorded')}</small></td><td>${lots.reduce((sum, lot) => sum + lotMovementHistory(state, lot.id).length, 0)} movements</td><td><div class="inventory-actions"><button class="icon-button" data-action="new-lot" data-material-id="${esc(material.id)}" type="button">Add lot</button><button class="icon-button" data-action="new-movement" data-material-id="${esc(material.id)}" type="button">Record movement</button></div></td></tr>`; }).join('')}</tbody></table>` : '<div class="empty-state"><strong>No materials recorded.</strong>Add only what you know; unknown supplier, quantity, and chemical properties stay visible as unknown.</div>';
  $('#recent-movements').innerHTML = summary.recentMovements.length ? summary.recentMovements.map(movement => `<article class="record"><div class="record-top"><strong>${esc(movement.movementType)}</strong><span class="record-date">${formatDate(movement.occurredAt)} · ${esc(movement.quantity)} ${esc(movement.unit)}</span></div><p class="record-summary">${esc(movement.note || 'No reason recorded.')}${movement.batchId ? ` · Batch ${esc(state.batches.find(batch => batch.id === movement.batchId)?.batchCode || movement.batchId)}` : ''}</p></article>`).join('') : '<div class="empty-state">No ledger movements yet.</div>';
}

function renderCompare() {
  const records = state.revisions.map(revision => { const experiment = getExperiment(revision.experimentId); return { value: revision.id, label: `${experiment?.experimentId || 'Experiment'} · Revision ${revision.revision} · ${experiment?.title || ''}`, revision, experiment }; });
  const options = records.map(record => `<option value="${esc(record.value)}">${esc(record.label)}</option>`).join(''); const a = $('#compare-a'); const b = $('#compare-b');
  const previousA = a.value; const previousB = b.value; a.innerHTML = options; b.innerHTML = options; a.value = records.some(record => record.value === previousA) ? previousA : records[0]?.value || ''; b.value = records.some(record => record.value === previousB) ? previousB : records[1]?.value || records[0]?.value || '';
  if (records.length < 2) { $('#comparison').innerHTML = '<div class="empty-state"><strong>Two revisions make a comparison.</strong>Create another formula revision to see changes side by side.</div>'; return; }
  const first = state.revisions.find(item => item.id === a.value) || state.revisions[0]; const second = state.revisions.find(item => item.id === b.value) || state.revisions[1];
  const comparison = compareRevisions(state, first.id, second.id);
  const changes = comparison.ingredientChanges.length ? comparison.ingredientChanges.map(change => `<li>${esc(change.kind)} · ${esc(change.after?.materialName || change.before?.materialName || change.key)}</li>`).join('') : '<li>No ingredient changes recorded.</li>';
  $('#comparison').innerHTML = [first, second].map(revision => { const experiment = getExperiment(revision.experimentId); const evaluations = revision.id === first.id ? comparison.leftEvaluations : comparison.rightEvaluations; const batches = revision.id === first.id ? comparison.leftBatchTotals : comparison.rightBatchTotals; return `<article class="comparison-card"><p class="label">REVISION ${revision.revision} · ${esc(experiment?.experimentId || '')}</p><h2>${esc(experiment?.title || 'Untitled experiment')}</h2><p>${esc(revision.notes || 'No revision notes recorded.')}</p><h3>INGREDIENTS</h3>${revision.ingredients?.length ? `<div class="chips">${revision.ingredients.map(item => `<span class="chip">${esc(item.materialName || item.materialId)} · ${esc(item.quantity)} ${esc(item.unit)}${item.lotId ? ` · lot ${esc(item.lotId)}` : ''}</span>`).join('')}</div>` : '<p>No ingredients recorded.</p>'}<h3>ACTUAL BATCHES</h3><p>${batches.length ? batches.map(batch => `${esc(batch.batchId)}: planned ${esc(batch.plannedAmount)} ${esc(batch.plannedUnit)}, actual ${batch.actual ? esc(batch.actual.totalAmount) : 'not recorded'} ${esc(batch.actual?.unit || batch.plannedUnit)}`).join('<br>') : 'No actual batch recorded.'}</p><h3>RECORDED EVIDENCE</h3><p>${evaluations.length} linked evaluation${evaluations.length === 1 ? '' : 's'} · ${evaluations.filter(item => item.isMeasured).length} marked measured · ${evaluations.filter(item => !item.isMeasured).length} subjective</p></article>`; }).join('') + `<div class="compare-note"><strong>Recorded ingredient changes</strong><ul>${changes}</ul>${comparison.warnings.length ? `<p>${comparison.warnings.map(warning => esc(warning)).join(' ')}</p>` : ''}<span>A changed score or descriptor is a recorded difference, not proof that one formula caused it. Compare conditions and evaluation intervals before drawing conclusions.</span></div>`;
}

function renderAll() { $('#stat-journal').textContent = state.journalEntries.length; $('#stat-experiments').textContent = state.experiments.filter(item => item.status !== 'Archived').length; $('#stat-maturing').textContent = state.experiments.filter(item => item.status === 'Maturing').length; $('#stat-evaluations').textContent = state.evaluations.length; const banner = $('#recovery-banner'); banner.hidden = !storageLocked; $('#recovery-message').textContent = loadError || 'Saved data is unreadable.'; renderJournal(); renderExperiments(); try { renderMaterials(); } catch (error) { console.error(error); $('#material-list').innerHTML = `<div class="empty-state"><strong>Inventory could not render.</strong>${esc(error.message)}</div>`; } renderCompare(); companionApi?.render(); }

function journalFormValues(form) { const values = Object.fromEntries(new FormData(form)); return { title: values.title, observedAt: new Date(`${values.observedAt}T12:00:00`).toISOString(), experimentId: values.experimentId || undefined, medium: values.medium, evaluationTimeMinutes: values.evaluationTimeMinutes ? Number(values.evaluationTimeMinutes) : undefined, purpose: values.purpose, hypothesis: values.purpose, opening: values.opening, heart: values.heart, dryDown: values.dryDown, overall: values.dryDown, descriptors: tags(values.descriptors), tags: tags(values.tags), intensity: values.intensity ? Number(values.intensity) : undefined, projection: values.projection ? Number(values.projection) : undefined, personalNotes: values.personalNotes, attachmentRefs: [] }; }
function showJournalForm(entry = null) { const form = $('#journal-form'); form.reset(); form.dataset.editId = entry?.id || ''; form.elements.experimentId.innerHTML = '<option value="">Not linked</option>' + state.experiments.map(item => `<option value="${esc(item.id)}">${esc(item.experimentId)} · ${esc(item.title)}</option>`).join(''); form.elements.observedAt.value = entry?.observedAt?.slice(0, 10) || today(); if (entry) for (const key of ['title', 'medium', 'purpose', 'opening', 'heart', 'dryDown', 'personalNotes', 'experimentId']) if (entry[key] != null && form.elements[key]) form.elements[key].value = entry[key]; form.elements.descriptors.value = entry?.descriptors?.join(', ') || ''; form.elements.tags.value = entry?.tags?.join(', ') || ''; form.elements.evaluationTimeMinutes.value = entry?.evaluationTimeMinutes || ''; form.elements.intensity.value = entry?.intensity || ''; form.elements.projection.value = entry?.projection || ''; $('#journal-dialog h2').textContent = entry ? 'Edit journal entry' : 'New journal entry'; openDialog('journal-dialog'); }

function showLegacyExperimentDetail(id) { const experiment = getExperiment(id); const revisions = state.revisions.filter(item => experiment.formulaRevisionIds.includes(item.id)); const batches = state.batches.filter(item => experiment.batchIds.includes(item.id)); const evaluations = state.evaluations.filter(item => experiment.evaluationIds?.includes(item.id)); $('#record-dialog-content').innerHTML = `<div class="dialog-content"><p class="label">${esc(experiment.experimentId)} · ${esc(experiment.status)}</p><h2>${esc(experiment.title)}</h2><p class="record-summary">${esc(experiment.objective)}</p><div class="chips"><span class="chip">Created ${formatDate(experiment.createdAt)}</span><span class="chip">${revisions.length} formula revisions</span><span class="chip">${batches.length} batches</span><span class="chip">${evaluations.length} evaluations</span></div><div class="form-actions"><button class="primary-button" data-action="new-revision" data-id="${esc(id)}">＋ Formula revision</button><button class="icon-button" data-action="new-batch" data-id="${esc(id)}">Record batch</button><button class="icon-button" data-action="new-evaluation" data-id="${esc(id)}">Add evaluation</button></div><h3>REVISION HISTORY</h3>${revisions.map(revision => `<div class="record"><strong>Revision ${revision.revision}</strong><span class="record-date"> · ${formatDate(revision.createdAt)}</span><p class="record-summary">${esc(revision.notes || 'No notes')}</p><div class="chips">${(revision.ingredients || []).map(item => `<span class="chip">${esc(item.materialName || item.materialId)} · ${esc(item.quantity)} ${esc(item.unit)}</span>`).join('')}</div></div>`).join('') || '<p class="muted">No revisions yet.</p>'}<h3>BATCH HISTORY</h3>${batches.map(batch => { const summary = batchSummary(batch); return `<div class="record"><strong>${esc(batch.batchCode)}</strong><p class="record-summary">Actual ${summary.totalAmount} ${summary.unit} · active amount ${summary.totalActiveAmount} ${summary.unit}</p></div>`; }).join('') || '<p class="muted">No batches yet.</p>'}</div>`; openDialog('record-dialog'); }

function showRevisionForm(experimentId) { const experiment = getExperiment(experimentId); $('#record-dialog-content').innerHTML = `<form id="revision-form" class="dialog-content" data-experiment-id="${esc(experimentId)}"><p class="label">${esc(experiment.experimentId)} · PRESERVED HISTORY</p><h2>New formula revision</h2><p class="muted">Revision ${experiment.formulaRevisionIds.length + 1} will supersede the current revision without changing it.</p><label>Revision notes<textarea name="notes" rows="3" required placeholder="What changed and why?"></textarea></label><label>Ingredients<textarea name="ingredients" rows="5" required placeholder="Material name | quantity | unit | concentration | role&#10;Cedar accord | 2 | g | 100 | base"></textarea></label><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experimentId)}">Cancel</button><button class="primary-button">Save revision</button></div></form>`; }
function showLegacyBatchForm(experimentId) { const experiment = getExperiment(experimentId); const revisions = state.revisions.filter(item => experiment.formulaRevisionIds.includes(item.id)); $('#record-dialog-content').innerHTML = `<form id="batch-form" class="dialog-content" data-experiment-id="${esc(experimentId)}"><p class="label">ACTUAL ADDITIONS · TRACEABLE</p><h2>Record a batch</h2><label>Formula revision<select name="formulaRevisionId">${revisions.map(item => `<option value="${esc(item.id)}">Revision ${item.revision}</option>`).join('')}</select></label><div class="form-grid"><label>Planned quantity<input name="plannedAmount" type="number" min="0.0001" step="0.0001" required></label><label>Unit<select name="unit"><option>g</option><option>mL</option></select></label></div><label>Actual additions<textarea name="additions" rows="5" required placeholder="Material ID or name | lot ID | amount | unit | concentration&#10+material-seed-1 | lot-seed-1 | 2 | g | 100"></textarea></label><label>Procedure / maturation notes<textarea name="procedureNotes" rows="3"></textarea></label><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experimentId)}">Cancel</button><button class="primary-button">Save batch</button></div></form>`; }
function showEvaluationForm(experimentId) { const experiment = getExperiment(experimentId); const batches = state.batches.filter(item => experiment.batchIds.includes(item.id)); $('#record-dialog-content').innerHTML = `<form id="evaluation-form" class="dialog-content" data-experiment-id="${esc(experimentId)}"><p class="label">SENSORY EVALUATION</p><h2>Record an observation</h2><div class="form-grid"><label>Interval label<input name="intervalLabel" placeholder="e.g. 24 hours"></label><label>Medium<select name="medium"><option>Blotter</option><option>Skin</option><option>Other</option></select></label><label>Batch<select name="batchId">${batches.map(item => `<option value="${esc(item.id)}">${esc(item.batchCode)}</option>`).join('')}</select></label><label>Evaluation date<input name="evaluatedAt" type="date" value="${today()}"></label></div><label>Descriptors<input name="descriptors" placeholder="green, woody, soft"></label><label>Subjective notes<textarea name="subjectiveNotes" rows="3"></textarea></label><label>Measured results (optional; include method)<textarea name="measuredResults" rows="3"></textarea></label><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experimentId)}">Cancel</button><button class="primary-button">Save evaluation</button></div></form>`; }

function batchAdditionRow(index, values = {}) {
  const materials = state.materials.map(material => `<option value="${esc(material.id)}" ${material.id === values.materialId ? 'selected' : ''}>${esc(material.name)}</option>`).join('');
  const material = state.materials.find(item => item.id === (values.materialId || state.materials[0]?.id));
  const lots = (material?.lots || []).map(lot => `<option value="${esc(lot.id)}" ${lot.id === values.materialLotId ? 'selected' : ''}>${esc(lot.lotCode || lot.id)} · ${esc(lot.receivedUnit || stockStatus(state, lot.id).unit || '?')}</option>`).join('');
  return `<div class="batch-addition-row" data-addition-index="${index}"><div class="form-grid"><label>Material<select name="materialId" data-role="addition-material" required>${materials}</select></label><label>Physical lot<select name="materialLotId" data-role="addition-lot" required>${lots}</select></label><label>Actual quantity<input name="amount" type="number" min="0.0001" step="0.0001" value="${esc(values.amount ?? '')}" required></label><label>Unit<select name="unit"><option value="mg" ${values.unit === 'mg' ? 'selected' : ''}>mg</option><option value="g" ${values.unit === 'g' || !values.unit ? 'selected' : ''}>g</option><option value="kg" ${values.unit === 'kg' ? 'selected' : ''}>kg</option><option value="mL" ${values.unit === 'mL' ? 'selected' : ''}>mL</option><option value="L" ${values.unit === 'L' ? 'selected' : ''}>L</option></select></label><label>Concentration (%)<input name="concentration" type="number" min="0" max="100" step="0.01" value="${esc(values.concentration ?? 100)}"></label><label>Added at<input name="addedAt" type="datetime-local" value="${esc(values.addedAt || '')}"></label></div><button type="button" class="text-button" data-action="remove-batch-addition">Remove addition</button></div>`;
}

function renderBatchAdditionRows(form, rows) { $('#batch-additions').innerHTML = rows.map((values, index) => batchAdditionRow(index, values)).join(''); }

function showBatchForm(experimentId) {
  const experiment = getExperiment(experimentId); const revisions = state.revisions.filter(item => experiment.formulaRevisionIds.includes(item.id)); const revision = revisions.at(-1);
  const seedRows = (revision?.ingredients || []).map(ingredient => ({ materialId: ingredient.materialId, materialLotId: ingredient.lotId || state.materials.find(item => item.id === ingredient.materialId)?.lots?.[0]?.id, amount: ingredient.quantity, unit: ingredient.unit, concentration: ingredient.stockConcentration ?? 100 }));
  $('#record-dialog-content').innerHTML = `<form id="batch-form" class="dialog-content" data-experiment-id="${esc(experimentId)}"><p class="label">PHYSICAL BATCH · TRACEABLE</p><h2>Record what was actually mixed</h2><p class="muted"><strong>${esc(experiment.experimentId)} · ${esc(experiment.title)}</strong><br>Choose one exact formula revision. Planned quantities remain unchanged; each row below creates one lot-specific stock consumption.</p><div class="form-grid"><label>Formula revision<select name="formulaRevisionId" id="batch-form-revision">${revisions.map(item => `<option value="${esc(item.id)}" ${item.id === revision?.id ? 'selected' : ''}>Revision ${item.revision} · ${esc(item.notes || 'No notes')}</option>`).join('')}</select></label><label>Batch identifier<input name="batchCode" required placeholder="BATCH-004"></label><label>Planned batch size<input name="plannedAmount" type="number" min="0.0001" step="0.0001" required></label><label>Unit<select name="unit"><option>mg</option><option selected>g</option><option>kg</option><option>mL</option><option>L</option></select></label><label>Mixing date/time<input name="mixingDate" type="datetime-local" required></label></div><div class="section-heading"><div><p class="label">ACTUAL ADDITIONS</p><h3>One row per physical addition</h3></div><button type="button" class="secondary-button" data-action="add-batch-addition">＋ Add row</button></div><div id="batch-additions"></div><label>Procedure notes<textarea name="procedureNotes" rows="3" placeholder="Order of addition, temperature, mixing method…"></textarea></label><label>Relevant observations<textarea name="observations" rows="2" placeholder="Appearance, clarity, unexpected behavior…"></textarea></label><label>Deviations from plan<textarea name="deviations" rows="2" placeholder="Record deviations; do not edit the formula revision."></textarea></label><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experimentId)}">Cancel</button><button class="primary-button">Append physical batch</button></div></form>`;
  const form = $('#batch-form'); form.elements.plannedAmount.value = revision?.ingredients?.reduce((sum, item) => item.unit === (revision.ingredients[0]?.unit || 'g') ? sum + item.quantity : sum, 0) || ''; form.elements.mixingDate.value = new Date().toISOString().slice(0, 16); renderBatchAdditionRows(form, seedRows.length ? seedRows : [{}]);
}

function showBatchDetail(batchId, experimentId) {
  const batch = state.batches.find(item => item.id === batchId); const experiment = getExperiment(experimentId || batch?.experimentId); if (!batch || !experiment) return;
  const revision = state.revisions.find(item => item.id === batch.formulaRevisionId); const comparison = compareBatchToPlan(state, batch.id); const summary = batchSummary(batch); const rowStatus = row => row.status === 'missing' ? 'Missing' : row.status === 'deviates' ? 'Deviation' : 'Matched';
  $('#record-dialog-content').innerHTML = `<div class="dialog-content"><p class="label">${esc(experiment.experimentId)} · PHYSICAL BATCH</p><h2>${esc(batch.batchCode)}</h2><p class="record-summary">Revision ${esc(revision?.revision || '?')} · mixed ${formatDate(batch.mixingDate)} · planned ${esc(batch.plannedAmount)} ${esc(batch.unit)} · actual ${esc(summary.totalAmount.toFixed(4))} ${esc(summary.unit)}</p><div class="chips"><span class="chip">${comparison.totalDifference >= 0 ? '+' : ''}${comparison.totalDifference.toFixed(4)} ${esc(comparison.unit)} vs formula ingredients</span><span class="chip">${batch.actualAdditions.length} actual additions</span><span class="chip">${batch.actualAdditions.filter(item => item.stockMovementId).length} linked movements</span></div><h3>PLANNED VS ACTUAL</h3><div class="table-wrap"><table><thead><tr><th>PLANNED MATERIAL</th><th>PLANNED</th><th>ACTUAL</th><th>DIFFERENCE</th><th>STATUS</th></tr></thead><tbody>${comparison.rows.map(row => `<tr><td>${esc(row.materialName)}${row.lotId ? `<br><small class="muted">Lot ${esc(lotMovementHistory(state, row.lotId)[0]?.materialLotId || row.lotId)}</small>` : ''}</td><td>${esc(row.amountInBatchUnit.toFixed(4))} ${esc(comparison.unit)}</td><td>${esc(row.actualAmount.toFixed(4))} ${esc(comparison.unit)}</td><td>${row.difference >= 0 ? '+' : ''}${esc(row.difference.toFixed(4))} ${esc(comparison.unit)}</td><td>${rowStatus(row)}</td></tr>`).join('')}${comparison.extraAdditions.map(addition => `<tr><td>${esc(addition.materialName)}<br><small class="muted">Extra · lot ${esc(addition.lotCode)}</small></td><td>—</td><td>${esc(addition.amountInBatchUnit.toFixed(4))} ${esc(comparison.unit)}</td><td>+${esc(addition.amountInBatchUnit.toFixed(4))} ${esc(comparison.unit)}</td><td>Extra</td></tr>`).join('')}</tbody></table></div><h3>ACTUAL LOT USE</h3><ul>${batch.actualAdditions.map(addition => { const material = state.materials.find(item => item.id === addition.materialId); const lot = material?.lots?.find(item => item.id === addition.materialLotId); const movement = state.stockMovements.find(item => item.id === addition.stockMovementId); return `<li>${esc(material?.name || addition.materialId)} · lot ${esc(lot?.lotCode || addition.materialLotId)} · ${esc(addition.amount)} ${esc(addition.unit)} · movement ${esc(movement?.id || addition.stockMovementId)}</li>`; }).join('')}</ul><h3>PROCESS RECORD</h3><p>${esc(batch.procedureNotes || 'No procedure notes recorded.')}</p><p>${esc(batch.observations || 'No relevant observations recorded.')}</p><p><strong>Deviations:</strong> ${esc(batch.deviations || 'None recorded.')}</p><div class="form-actions"><button type="button" class="text-button" data-action="back-experiment" data-id="${esc(experiment.id)}">Back to experiment</button></div></div>`;
}

function showExperimentDetail(id) {
  const experiment = getExperiment(id); const revisions = state.revisions.filter(item => experiment.formulaRevisionIds.includes(item.id)); const batches = state.batches.filter(item => experiment.batchIds.includes(item.id)); const evaluations = state.evaluations.filter(item => experiment.evaluationIds?.includes(item.id));
  $('#record-dialog-content').innerHTML = `<div class="dialog-content"><p class="label">${esc(experiment.experimentId)} · ${esc(experiment.status)}</p><h2>${esc(experiment.title)}</h2><p class="record-summary">${esc(experiment.objective)}</p><div class="chips"><span class="chip">Created ${formatDate(experiment.createdAt)}</span><span class="chip">${revisions.length} formula revisions</span><span class="chip">${batches.length} physical batches</span><span class="chip">${evaluations.length} evaluations</span></div><div class="form-actions"><button class="primary-button" data-action="new-revision" data-id="${esc(id)}">＋ Formula revision</button><button class="icon-button" data-action="new-batch" data-id="${esc(id)}">Record physical batch</button><button class="icon-button" data-action="new-evaluation" data-id="${esc(id)}">Add evaluation</button></div><h3>REVISION HISTORY</h3>${revisions.map(revision => `<div class="record"><strong>Revision ${revision.revision}</strong><span class="record-date"> · ${formatDate(revision.createdAt)}</span><p class="record-summary">${esc(revision.notes || 'No notes')}</p><div class="chips">${(revision.ingredients || []).map(item => `<span class="chip">${esc(item.materialName || item.materialId)} · ${esc(item.quantity)} ${esc(item.unit)}${item.lotId ? ` · lot ${esc(item.lotId)}` : ''}</span>`).join('')}</div></div>`).join('') || '<p class="muted">No revisions yet.</p>'}<h3>PHYSICAL BATCH HISTORY</h3>${batches.map(batch => { const summary = batchSummary(batch); return `<div class="record"><div class="record-top"><div><strong>${esc(batch.batchCode)}</strong><span class="record-date"> · ${formatDate(batch.mixingDate)}</span></div><button class="icon-button" data-action="open-batch" data-id="${esc(batch.id)}" data-experiment-id="${esc(experiment.id)}">Review batch</button></div><p class="record-summary">Planned ${esc(batch.plannedAmount)} ${esc(batch.unit)} · actual ${esc(summary.totalAmount.toFixed(4))} ${esc(summary.unit)} · ${batch.actualAdditions.length} additions</p></div>`; }).join('') || '<p class="muted">No physical batches yet. Planned formulas do not consume stock.</p>'}<h3>EVALUATIONS</h3><p>${evaluations.length ? evaluations.map(item => `${esc(item.intervalLabel || 'Observation')} · ${formatDate(item.evaluatedAt)} · ${esc(item.subjectiveNotes || 'No notes')}`).join('<br>') : 'No evaluations yet.'}</p></div>`; openDialog('record-dialog');
}

document.querySelectorAll('[data-screen]').forEach(button => button.addEventListener('click', () => { currentScreen = button.dataset.screen; document.querySelectorAll('.nav').forEach(item => item.classList.toggle('active', item === button)); document.querySelectorAll('[data-screen-panel]').forEach(panel => panel.classList.toggle('hidden', panel.id !== `screen-${currentScreen}`)); $('#breadcrumb').textContent = button.textContent.trim(); if (currentScreen === 'compare') renderCompare(); if (currentScreen === 'materials') { try { renderMaterials(); } catch (error) { toast(`Inventory error: ${error.message}`); } } window.scrollTo({ top: 0, behavior: 'smooth' }); }));
document.querySelectorAll('[data-close]').forEach(button => button.addEventListener('click', () => closeDialog(button.dataset.close)));
document.addEventListener('click', event => {
  const action = event.target.closest('[data-action]'); if (!action) return;
  const type = action.dataset.action;
  if (type === 'new-journal') showJournalForm();
  if (type === 'new-experiment') { $('#experiment-form').reset(); openDialog('experiment-dialog'); }
  if (type === 'new-material') { $('#material-form').reset(); openDialog('material-dialog'); }
   if (type === 'new-movement') { showMovementForm(action.dataset.materialId, action.dataset.lotId); }
   if (type === 'new-lot') { showLotForm(action.dataset.materialId); }
   if (type === 'reconcile-lot') { showReconcileForm(action.dataset.lotId); }
  if (type === 'open-journal') showJournalForm(state.journalEntries.find(item => item.id === action.closest('[data-journal-id]').dataset.journalId));
  if (type === 'duplicate-journal') { const source = state.journalEntries.find(item => item.id === action.closest('[data-journal-id]').dataset.journalId); showJournalForm({ ...source, id: '' , title: `${source.title} — copy` }); }
   if (type === 'new-revision') showRevisionForm(action.dataset.id);
   if (type === 'new-batch') showBatchForm(action.dataset.id);
   if (type === 'open-batch') showBatchDetail(action.dataset.id, action.dataset.experimentId);
   if (type === 'add-batch-addition') { const rows = [...document.querySelectorAll('#batch-additions .batch-addition-row')].map(row => ({ materialId: row.querySelector('[data-role="addition-material"]')?.value, materialLotId: row.querySelector('[data-role="addition-lot"]')?.value, amount: row.querySelector('[name="amount"]')?.value, unit: row.querySelector('[name="unit"]')?.value, concentration: row.querySelector('[name="concentration"]')?.value, addedAt: row.querySelector('[name="addedAt"]')?.value })); rows.push({}); renderBatchAdditionRows($('#batch-form'), rows); }
   if (type === 'remove-batch-addition') { const rows = [...document.querySelectorAll('#batch-additions .batch-addition-row')]; if (rows.length > 1) action.closest('.batch-addition-row').remove(); }
   if (type === 'new-evaluation') showEvaluationForm(action.dataset.id);
  if (type === 'back-experiment') showExperimentDetail(action.dataset.id);
 });
document.addEventListener('change', event => {
  if (event.target.matches('[data-role="addition-material"]')) {
    const row = event.target.closest('.batch-addition-row'); const material = state.materials.find(item => item.id === event.target.value); const lotSelect = row.querySelector('[data-role="addition-lot"]'); lotSelect.innerHTML = (material?.lots || []).map(lot => `<option value="${esc(lot.id)}">${esc(lot.lotCode || lot.id)} · ${esc(lot.receivedUnit || stockStatus(state, lot.id).unit || '?')}</option>`).join(''); const lot = material?.lots?.[0]; if (lot) row.querySelector('[name="unit"]').value = lot.receivedUnit || stockStatus(state, lot.id).unit || 'g';
  }
  if (event.target.id === 'batch-form-revision') {
    const revision = state.revisions.find(item => item.id === event.target.value); const rows = (revision?.ingredients || []).map(ingredient => ({ materialId: ingredient.materialId, materialLotId: ingredient.lotId || state.materials.find(item => item.id === ingredient.materialId)?.lots?.[0]?.id, amount: ingredient.quantity, unit: ingredient.unit, concentration: ingredient.stockConcentration ?? 100 })); renderBatchAdditionRows($('#batch-form'), rows.length ? rows : [{}]);
  }
});
