$('#journal-search').addEventListener('input', renderJournal); $('#journal-filter').addEventListener('change', renderJournal); $('#experiment-search').addEventListener('input', renderExperiments); $('#experiment-status').addEventListener('change', renderExperiments); $('#compare-a').addEventListener('change', renderCompare); $('#compare-b').addEventListener('change', renderCompare);

$('#journal-form').addEventListener('submit', event => { event.preventDefault(); const values = journalFormValues(event.target); const editId = event.target.dataset.editId; try { const next = editId ? updateJournalEntry(state, editId, values) : addJournalEntry(state, values); if (persist(next)) { closeDialog('journal-dialog'); toast(editId ? 'Journal entry updated' : 'Journal entry saved'); } } catch (error) { toast(error.message); } });
$('#experiment-form').addEventListener('submit', event => { event.preventDefault(); const next = addExperiment(state, Object.fromEntries(new FormData(event.target))); if (persist(next)) { closeDialog('experiment-dialog'); toast('Experiment created'); } });
function showMovementForm(materialId = '', lotId = '') { const form = $('#movement-form'); form.reset(); const materialSelect = $('#movement-material'); materialSelect.innerHTML = state.materials.map(material => `<option value="${esc(material.id)}">${esc(material.name)}</option>`).join(''); materialSelect.value = materialId || state.materials[0]?.id || ''; const updateLots = () => { const material = state.materials.find(item => item.id === materialSelect.value); $('#movement-lot').innerHTML = (material?.lots || []).map(lot => `<option value="${esc(lot.id)}">${esc(lot.lotCode || lot.id)} · ${esc(lot.receivedUnit || 'unit unknown')}</option>`).join(''); if (lotId && material?.lots?.some(lot => lot.id === lotId)) $('#movement-lot').value = lotId; const lot = material?.lots?.find(item => item.id === $('#movement-lot').value) || material?.lots?.[0]; if (lot) { form.elements.unit.value = lot.receivedUnit || stockStatus(state, lot.id).unit || ''; $('#movement-reference').innerHTML = '<option value="">Not required</option>' + state.stockMovements.filter(item => item.materialLotId === lot.id).map(item => `<option value="${esc(item.id)}">${esc(item.movementType)} · ${esc(item.quantity)} ${esc(item.unit)} · ${formatDate(item.occurredAt)}</option>`).join(''); } }; materialSelect.onchange = updateLots; $('#movement-lot').onchange = updateLots; updateLots(); openDialog('movement-dialog'); }
function showLotForm(materialId) { const form = $('#lot-form'); form.reset(); form.elements.materialId.value = materialId; $('#lot-material-name').textContent = `Adding a physical lot to ${state.materials.find(item => item.id === materialId)?.name || 'material'}.`; openDialog('lot-dialog'); }
function showReconcileForm(lotId) { const { material, lot } = state.materials.flatMap(item => (item.lots || []).map(candidate => ({ material: item, lot: candidate }))).find(item => item.lot.id === lotId) || {}; if (!lot) return; const form = $('#reconcile-form'); form.reset(); const status = stockStatus(state, lotId); form.elements.materialLotId.value = lotId; form.elements.recorded.value = status.balanceKnown ? `${status.balance.toFixed(4)} ${status.unit}` : 'Unknown — opening not established'; form.elements.unit.value = status.unit; $('#reconcile-lot-name').textContent = `${material.name} · ${lot.lotCode || lot.id}`; const quantityLabel = form.elements.physicalQuantity.closest('label'); quantityLabel.firstChild.textContent = status.balanceKnown ? 'Physical count' : 'Measured opening quantity'; $('#reconcile-variance').textContent = status.balanceKnown ? 'Enter a physical count to preview the variance.' : 'No trustworthy opening was recorded. Enter a measured opening quantity; historical consumption remains preserved.'; form.elements.physicalQuantity.disabled = false; form.elements.reason.disabled = false; form.querySelector('button.primary-button').disabled = false; openDialog('reconcile-dialog'); }
$('#movement-form').addEventListener('submit', event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target)); try { const next = addStockMovement(state, { materialId: values.materialId, materialLotId: values.materialLotId, movementType: values.movementType, direction: values.direction, quantity: Number(values.quantity), unit: values.unit, referenceMovementId: values.referenceMovementId || undefined, verified: values.verified === 'on', confirmedReturn: values.confirmedReturn === 'on', occurredAt: values.occurredAt ? new Date(values.occurredAt).toISOString() : undefined, note: values.note }); if (persist(next)) { closeDialog('movement-dialog'); toast('Stock movement appended'); } } catch (error) { toast(error.message); } });
$('#reconcile-form').addEventListener('input', event => { if (event.target.name !== 'physicalQuantity') return; const form = event.currentTarget; const lotId = form.elements.materialLotId.value; const status = stockStatus(state, lotId); const physical = Number(form.elements.physicalQuantity.value); if (!Number.isFinite(physical) || physical < 0) { $('#reconcile-variance').textContent = 'Enter a valid non-negative quantity.'; return; } if (!status.balanceKnown) { $('#reconcile-variance').textContent = `Measured opening: ${physical.toFixed(4)} ${status.unit}. This will establish the opening and preserve prior history.`; return; } const variance = physical - status.balance; $('#reconcile-variance').textContent = `Variance: ${variance >= 0 ? '+' : ''}${variance.toFixed(4)} ${status.unit}. This will append a verified ${variance >= 0 ? 'increase' : 'decrease'} adjustment; history is not edited.`; $('#reconcile-variance').className = `result-card ${variance >= 0 ? 'variance-positive' : 'variance-negative'}`; });
$('#reconcile-form').addEventListener('submit', event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target)); try { const status = stockStatus(state, values.materialLotId); if (!status.balanceKnown) { const next = reconcileLotOpening(state, values.materialLotId, { quantity: Number(values.physicalQuantity), unit: values.unit, note: values.reason }); if (persist(next)) { closeDialog('reconcile-dialog'); toast(`Opening balance established at ${values.physicalQuantity} ${values.unit}`); } return; } const result = reconcileLot(state, values.materialLotId, { physicalQuantity: Number(values.physicalQuantity), unit: values.unit, reason: values.reason }); if (persist(result.state)) { closeDialog('reconcile-dialog'); toast(`Reconciliation saved; variance ${result.variance >= 0 ? '+' : ''}${result.variance.toFixed(4)} ${values.unit}`); } } catch (error) { toast(error.message); } });
$('#material-form').addEventListener('submit', event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target)); try { let next = addMaterial(state, values); const materialId = next.materials[0].id; if (values.lotCode) next = addMaterialLot(next, materialId, { ...values, receivedAmount: values.receivedAmount ? Number(values.receivedAmount) : undefined, lowStockThreshold: values.lowStockThreshold ? Number(values.lowStockThreshold) : undefined, purity: values.purity ? Number(values.purity) : undefined, stockConcentration: values.stockConcentration ? Number(values.stockConcentration) : undefined, density: values.density ? Number(values.density) : undefined, receivedUnit: values.receivedUnit || undefined, receivedAt: values.acquiredAt || undefined }); if (persist(next)) { closeDialog('material-dialog'); toast('Material added to ledger'); } } catch (error) { toast(error.message); } });
$('#lot-form').addEventListener('submit', event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target)); try { const next = addMaterialLot(state, values.materialId, { ...values, receivedAmount: values.receivedAmount ? Number(values.receivedAmount) : undefined, lowStockThreshold: values.lowStockThreshold ? Number(values.lowStockThreshold) : undefined, purity: values.purity ? Number(values.purity) : undefined, stockConcentration: values.stockConcentration ? Number(values.stockConcentration) : undefined, density: values.density ? Number(values.density) : undefined, receivedUnit: values.receivedUnit || undefined }); if (persist(next)) { closeDialog('lot-dialog'); toast('Physical lot added'); } } catch (error) { toast(error.message); } });
$('#dilution-form').addEventListener('submit', event => { event.preventDefault(); const values = Object.fromEntries(new FormData(event.target)); const error = $('#calculator-error'); try { const result = calculateDilution({ stockConcentration: Number(values.stock), targetConcentration: Number(values.target), finalAmount: Number(values.amount), unit: values.unit }); error.textContent = ''; $('#calculator-result').classList.remove('empty-card'); $('#calculator-result').innerHTML = `<p class="label">CALCULATED RESULT · ${esc(result.unit)}</p><h2>${result.targetConcentration}% final concentration</h2><div class="result-lines"><div class="result-line"><span>Required stock</span><strong>${result.stockAmount.toFixed(4)} ${esc(result.unit)}</strong></div><div class="result-line"><span>Required diluent</span><strong>${result.diluentAmount.toFixed(4)} ${esc(result.unit)}</strong></div><div class="result-line"><span>Final quantity</span><strong>${result.finalAmount.toFixed(4)} ${esc(result.unit)}</strong></div></div><p class="muted">Formula: final × target ÷ stock. Calculated values are separate from measured additions.</p>`; } catch (calculationError) { error.textContent = calculationError.message; } });
$('#record-dialog').addEventListener('submit', event => { event.preventDefault(); const form = event.target; try { if (form.id === 'batch-form') { if (!window.confirm('Append this physical batch and deduct stock from each selected lot?')) return; const actualAdditions = [...form.querySelectorAll('.batch-addition-row')].map(row => { const values = Object.fromEntries(new FormData(row)); return { id: values.id || `addition-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 5)}`, materialId: values.materialId, materialLotId: values.materialLotId, amount: Number(values.amount), unit: values.unit, concentration: values.concentration === '' ? 100 : Number(values.concentration), addedAt: values.addedAt ? new Date(values.addedAt).toISOString() : new Date().toISOString() }; }); const next = addBatch(state, form.dataset.experimentId, { formulaRevisionId: form.elements.formulaRevisionId.value, batchCode: form.elements.batchCode.value, plannedAmount: Number(form.elements.plannedAmount.value), unit: form.elements.unit.value, mixingDate: new Date(form.elements.mixingDate.value).toISOString(), procedureNotes: form.elements.procedureNotes.value, observations: form.elements.observations.value, deviations: form.elements.deviations.value, actualAdditions }); if (persist(next)) { closeDialog('record-dialog'); toast('Physical batch appended and stock deducted'); showExperimentDetail(form.dataset.experimentId); } return; } if (form.id === 'revision-form') { const ingredients = form.elements.ingredients.value.split('\n').map(line => line.split('|').map(part => part.trim())).filter(parts => parts.length >= 3 && parts[0]).map(parts => ({ materialId: parts[0], materialName: parts[0], quantity: Number(parts[1]), unit: parts[2], stockConcentration: parts[3] ? Number(parts[3]) : undefined, role: parts[4] || '' })); persist(addRevision(state, form.dataset.experimentId, { notes: form.elements.notes.value, ingredients })); showExperimentDetail(form.dataset.experimentId); toast('Formula revision preserved'); }
    if (form.id === 'batch-form') { const values = Object.fromEntries(new FormData(form)); const actualAdditions = values.additions.split('\n').map(line => line.replace(/^\+/, '').split('|').map(part => part.trim())).filter(parts => parts.length >= 4 && parts[0]).map(parts => ({ id: `addition-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 5)}`, materialId: parts[0], materialLotId: parts[1], amount: Number(parts[2]), unit: parts[3], concentration: parts[4] ? Number(parts[4]) : 100, addedAt: new Date().toISOString() })); persist(addBatch(state, form.dataset.experimentId, { formulaRevisionId: values.formulaRevisionId, plannedAmount: Number(values.plannedAmount), unit: values.unit, actualAdditions, procedureNotes: values.procedureNotes })); showExperimentDetail(form.dataset.experimentId); toast('Actual batch additions recorded'); }
    if (form.id === 'evaluation-form') { const values = Object.fromEntries(new FormData(form)); persist(addEvaluation(state, form.dataset.experimentId, { batchId: values.batchId, evaluatedAt: new Date(`${values.evaluatedAt}T12:00:00`).toISOString(), intervalLabel: values.intervalLabel, medium: values.medium, descriptors: tags(values.descriptors), subjectiveNotes: values.subjectiveNotes, measuredResults: values.measuredResults, isMeasured: Boolean(values.measuredResults) })); showExperimentDetail(form.dataset.experimentId); toast('Sensory evaluation recorded'); }
  } catch (error) { toast(error.message); } });
$('#export-button').addEventListener('click', () => { const blob = new Blob([serializeBackup(state)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = 'atelier-scent-lab-backup-v1.json'; anchor.click(); URL.revokeObjectURL(url); toast('Versioned backup exported'); });
$('#import-button').addEventListener('click', () => $('#import-file').click());
$('#import-file').addEventListener('change', async event => { const file = event.target.files?.[0]; if (!file) return; try { pendingBackup = parseBackup(await file.text()); const preview = previewBackupImport(state, pendingBackup, { mode: storageLocked ? 'replace' : 'merge', locked: storageLocked }); const recordCount = preview.imported + (preview.conflicts?.length || 0); $('#import-preview').textContent = storageLocked ? `Schema ${pendingBackup.schemaVersion}, exported ${pendingBackup.exportedAt || 'at an unknown time'}. The saved state is locked, so only Replace is available. The validated backup contains ${preview.imported} records.` : `Schema ${pendingBackup.schemaVersion}, exported ${pendingBackup.exportedAt || 'at an unknown time'}. Merge preview: ${recordCount} incoming records, ${preview.imported} new records, ${preview.conflicts?.length || 0} conflicts kept local. Replace validates the complete payload and writes it only after validation.`; $('#import-merge').disabled = storageLocked; openDialog('import-dialog'); } catch (error) { toast(error.message); } finally { event.target.value = ''; } });
function finishImport(mode) { const result = applyBackupImport(persistence, pendingBackup, { mode, currentState: state, locked: storageLocked }); if (!result.ok) { if (pendingBackup && result.error !== 'No backup is pending.') toast(result.error); return; } state = result.state; storageLocked = result.locked; $('#import-merge').disabled = false; closeDialog('import-dialog'); pendingBackup = null; renderAll(); companionApi?.render(); toast(mode === 'merge' ? `Backup merged; ${result.imported} records added${result.conflicts.length ? `, ${result.conflicts.length} conflicts kept local` : ''}.` : 'Backup restored'); }
$('#import-merge').addEventListener('click', () => finishImport('merge'));
$('#import-replace').addEventListener('click', () => finishImport('replace'));

companionApi = initScentCompanion({ getState: () => state, persist, toast, materialNames: ['Bergamot', 'Cedarwood', 'Iris', 'Rose', 'Sandalwood', 'Vetiver', 'Musk'] });
renderAll();
if (loadError) toast(loadError);
